var r=[{title:`Vad isolation betyder`,text:`En bicepscurl böjer främst armbågen, och en tricepsextension sträcker den. Lyft åt sidan betonar axelabduktion, bensparkar betonar knästräckning och bencurls betonar knäböjning. Ingen verklig rörelse rekryterar bara en muskel, så ”isolation” betyder att rörelsen är fokuserad på en led, medan andra muskler fortfarande hjälper till.`},{title:`När den är användbar`,text:`Isolation kan lägga till arbete för en eftersläpande muskel, hålla helkroppströttheten låg eller ge dig ett enkelt alternativ när balans och koordination är svåra. En rodd tränar till exempel bicepsen indirekt, men curls ger en mer direkt stimulans om armtillväxt är en prioritet. Maskiner kan göra riktad ansträngning särskilt lätt att kontrollera.`},{title:`Var den passar i ett pass`,text:`För allmän styrka kommer basövningar oftast först, medan du är pigg, och isolationsarbete följer som extra träning. Om en isolerad muskel är ditt huvudmål är det rimligt att träna den tidigt. Övningsordning är ett sätt att sätta prioriteringar, och du kan ändra den när dina prioriteringar ändras.`},{title:`Teknik och progression`,text:`Använd ett omfång som känns bekvämt i den arbetande leden, håll resten av kroppen stadig och svinga inte belastningen. Lägg till repetitioner eller en liten mängd vikt först när din form förblir densamma från repetition till repetition. Mycket lätta belastningar fungerar när ansträngningen är tillräckligt hög, och att lyfta ett tyngre tal bevisar inte att träningen är bättre. Håll dina totala set till vad du kan återhämta dig från. Om en rörelse orsakar smärta, avbryt den. TrainUp ger inga korrigerande rehabprogram.`}];var n=[{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: teknik vid styrketräning (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var a={sections:r,sources:n};export{a as default,r as sections,n as sources};